CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
INSERT INTO public.user_roles(user_id,role) SELECT id,'admin'::public.app_role FROM auth.users;
ALTER POLICY "Signed-in team can read" ON public.shop_state USING (public.has_role(auth.uid(),'admin'));
ALTER POLICY "Signed-in team can insert" ON public.shop_state WITH CHECK (id='main' AND public.has_role(auth.uid(),'admin'));
ALTER POLICY "Signed-in team can update" ON public.shop_state USING (id='main' AND public.has_role(auth.uid(),'admin')) WITH CHECK (id='main' AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.filaments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), material text NOT NULL CHECK(length(material) BETWEEN 1 AND 60), color text NOT NULL CHECK(length(color) BETWEEN 1 AND 60), color_hex text, best_used_for text NOT NULL DEFAULT '' CHECK(length(best_used_for)<=1000), in_stock boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.filaments TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.filaments TO authenticated; GRANT ALL ON public.filaments TO service_role;
ALTER TABLE public.filaments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public materials" ON public.filaments FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY "Team manages materials" ON public.filaments FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.inventory_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), description text CHECK(length(description)<=1000), price_cents integer NOT NULL DEFAULT 0 CHECK(price_cents>=0), quantity integer NOT NULL DEFAULT 0 CHECK(quantity>=0), image_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.inventory_items TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.inventory_items TO authenticated; GRANT ALL ON public.inventory_items TO service_role;
ALTER TABLE public.inventory_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public products" ON public.inventory_items FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY "Team manages products" ON public.inventory_items FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.quote_requests (id uuid PRIMARY KEY, customer_name text NOT NULL CHECK(length(trim(customer_name)) BETWEEN 1 AND 100), customer_email text NOT NULL CHECK(length(customer_email)<=255 AND customer_email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'), material text NOT NULL CHECK(length(material) BETWEEN 1 AND 60), color text NOT NULL CHECK(length(color) BETWEEN 1 AND 60), comment text CHECK(length(comment)<=1000), file_path text NOT NULL UNIQUE, file_name text NOT NULL CHECK(length(file_name) BETWEEN 1 AND 180), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','quoted','closed')), order_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.quote_requests TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.quote_requests TO authenticated; GRANT ALL ON public.quote_requests TO service_role;
ALTER TABLE public.quote_requests ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.valid_quote_file(request_id uuid, path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT path LIKE request_id::text || '/%' AND EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id='quote-files' AND name=path AND lower(storage.extension(name)) IN ('stl','3mf','obj','step','stp') AND COALESCE((metadata->>'size')::bigint,0) BETWEEN 1 AND 52428800) $$;
REVOKE ALL ON FUNCTION public.valid_quote_file(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.valid_quote_file(uuid,text) TO anon,authenticated;
CREATE POLICY "Submit new quote only" ON public.quote_requests FOR INSERT TO anon,authenticated WITH CHECK(status='new' AND order_id IS NULL AND public.valid_quote_file(id,file_path));
CREATE POLICY "Team reads quotes" ON public.quote_requests FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Team updates quotes" ON public.quote_requests FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Team deletes quotes" ON public.quote_requests FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Upload model only" ON storage.objects FOR INSERT TO anon,authenticated WITH CHECK(bucket_id='quote-files' AND name ~ '^[0-9a-f-]{36}/[A-Za-z0-9_.-]+\.(stl|3mf|obj|step|stp)$');
CREATE POLICY "Team reads models" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='quote-files' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Team deletes models" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='quote-files' AND public.has_role(auth.uid(),'admin'));
ALTER PUBLICATION supabase_realtime ADD TABLE public.quote_requests;